"use strict";(globalThis.webpackChunkmy_maker_blog=globalThis.webpackChunkmy_maker_blog||[]).push([[225],{3464:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/my-maker-blog/blog/welcome","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/welcome.md","source":"@site/blog/welcome.md","title":"Welcome to My Blog","description":"Welcome to my maker journey blog! This is where I\'ll share my projects, learnings, and experiences.","date":"2025-12-31T03:35:44.000Z","tags":[{"inline":true,"label":"welcome","permalink":"/my-maker-blog/blog/tags/welcome"}],"readingTime":0.1,"hasTruncateMarker":false,"authors":[{"name":"Sunny (Xinrong Sun)","title":"Maker & Student at Duke Kunshan University","url":"https://github.com/Sunny156-hungry","page":{"permalink":"/my-maker-blog/blog/authors/sunny"},"socials":{"github":"https://github.com/Sunny156-hungry"},"imageURL":"https://github.com/Sunny156-hungry.png","key":"sunny"}],"frontMatter":{"slug":"welcome","title":"Welcome to My Blog","authors":["sunny"],"tags":["welcome"]},"unlisted":false,"nextItem":{"title":"Twin Agents","permalink":"/my-maker-blog/blog/blog/twin-agents"}},"content":"Welcome to my maker journey blog! This is where I\'ll share my projects, learnings, and experiences.\\r\\n\\r\\nMore posts coming soon..."},{"id":"/blog/twin-agents","metadata":{"permalink":"/my-maker-blog/blog/blog/twin-agents","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/twin-agents/index.mdx","source":"@site/blog/twin-agents/index.mdx","title":"Twin Agents","description":"An interactive AI project featuring Schopenhauer and Hegel","date":"2025-12-31T00:00:00.000Z","tags":[{"inline":true,"label":"ai","permalink":"/my-maker-blog/blog/tags/ai"},{"inline":true,"label":"philosophy","permalink":"/my-maker-blog/blog/tags/philosophy"},{"inline":true,"label":"multi-agent","permalink":"/my-maker-blog/blog/tags/multi-agent"}],"readingTime":1.53,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Twin Agents","date":"2025-12-31T00:00:00.000Z","slug":"/blog/twin-agents","tags":["ai","philosophy","multi-agent"],"image":"/img/cover.jpg","description":"An interactive AI project featuring Schopenhauer and Hegel"},"unlisted":false,"prevItem":{"title":"Welcome to My Blog","permalink":"/my-maker-blog/blog/welcome"}},"content":"## Project Introduction\\r\\n\\r\\n**Twin Agents** is an interactive AI project featuring two philosophical agents modeled after **Arthur Schopenhauer** and **Georg Wilhelm Friedrich Hegel**.\\r\\n\\r\\nUsers can engage in conversations with each agent individually or observe dialogues between the two. Through these interactions, the project aims to spark curiosity about philosophy and help users gain a deeper, more accessible understanding of philosophical ideas.\\r\\n\\r\\n\\r\\n## \ud83c\udfa5 Project Demo\\r\\n\\r\\n\\r\\n<iframe\\r\\n  src=\\"https://player.bilibili.com/player.html?bvid=BV15JrNBgEDD&high_quality=1\\"\\r\\n  style={{ width: \\"100%\\", height: \\"420px\\", borderRadius: \\"12px\\" }}\\r\\n  frameBorder=\\"0\\"\\r\\n  allow=\\"autoplay; fullscreen; picture-in-picture\\"\\r\\n  allowFullScreen\\r\\n/>\\r\\n\\r\\n## Key Features\\r\\n\\r\\n- Two AI agents collaborate to overcome common issues in one-on-one AI conversations, such as boredom, stalled discussions, and informational echo chambers.\\r\\n- The project explores the concept of **1 + 1 > 2** in multi-agent intelligence.\\r\\n- The agents tease each other, debate opposing viewpoints, and generate intellectual friction, encouraging users to think critically and stay engaged.\\r\\n\\r\\n\\r\\n## Target Users\\r\\n\\r\\n- Philosophy enthusiasts  \\r\\n- General audiences with little or no formal background in philosophy\\r\\n\\r\\n\\r\\n## Why This Project\\r\\n\\r\\nMany people today perceive philosophy as distant from everyday life and therefore unimportant.  \\r\\nThis project challenges that perception by presenting philosophy as **lively, conversational, and relevant**, encouraging reflection and intellectual curiosity through an engaging AI-based device.\\r\\n\\r\\n\\r\\n## Challenges\\r\\n\\r\\n- Flashing, configuring, and assembling the XiaoZhi AI hardware\\r\\n- Coordinating stable interaction between the two agents\\r\\n\\r\\n\\r\\n## Unique Characteristics\\r\\n\\r\\n- The choice of **Schopenhauer and Hegel** is intentional: their philosophical disagreements create natural tension and contrasting worldviews.\\r\\n- The physical shell is designed as a trendy **\u201cElegant Gentleman\u201d penguin**, serving as a visual hook and lowering the entry barrier to philosophical engagement.\\r\\n\\r\\n\\r\\n## Next Steps\\r\\n\\r\\nFuture development will explore additional applications of twin-agent systems.  \\r\\nOne example is a **vocabulary-learning mode** featuring two Minion-style agents:\\r\\n- One acts as the quiz master\\r\\n- The other provides encouragement, hints, and emotional support\\r\\n\\r\\nThis makes learning more interactive, motivating, and emotionally engaging."}]}}')}}]);